() => {
  const text = document.body.innerText;
  const hasModalText = text.includes('技能库管理');
  // look for dialog/modal-like containers
  const dialogs = Array.from(document.querySelectorAll('[role="dialog"], [class*="modal" i], [class*="Modal" i], [class*="dialog" i], [class*="Drawer" i], [class*="overlay" i], [class*="Overlay" i]'));
  const info = dialogs.map(d => ({tag: d.tagName, cls: d.className && d.className.baseVal !== undefined ? d.getAttribute('class') : d.className, visible: d.offsetParent !== null, text: (d.innerText||'').slice(0,200)}));
  return {hasModalText, dialogCount: dialogs.length, info};
}

() => {
  const find = (t) => Array.from(document.querySelectorAll('*')).filter(el => el.children.length === 0 && el.textContent && el.textContent.trim() === t).map(el => {
    let n = el, chain = [];
    for (let i=0;i<5 && n;i++){ chain.push(n.tagName + (n.className && typeof n.className==='string' ? '.'+n.className.split(' ')[0] : '')); n = n.parentElement; }
    return {tag: el.tagName, visible: el.offsetParent !== null, chain: chain.join(' > ')};
  });
  return {
    mySkillTab: find('我的技能库'),
    sysSkillTab: find('系统技能库'),
    modalTitle: find('技能库管理').length
  };
}

() => {
  const body = document.body.innerText;
  const all = Array.from(document.querySelectorAll('div,section,aside'));
  const modalCandidates = all.filter(el => {
    const s = getComputedStyle(el);
    return (s.position === 'fixed' || s.position === 'absolute') && s.display !== 'none' && el.offsetWidth > 200;
  });
  return {
    hasMyTab: body.includes('我的技能库'),
    hasSysTab: body.includes('系统技能库'),
    fixedCount: modalCandidates.length,
    fixedTexts: modalCandidates.slice(0,5).map(el => (el.innerText||'').replace(/\s+/g,' ').slice(0,150))
  };
}

